<?php
namespace App\Services;
use App\Support\Database;use App\Support\TenantContext;use App\Support\Auth;
final class ApprovalService { public function request(string $type,?int $clientId=null,?int $clientServiceId=null,?int $workflowId=null,?int $roleId=null):int{$s=Database::pdo()->prepare('INSERT INTO approvals(tenant_id,client_id,client_service_id,workflow_execution_id,approval_type,required_role_id,status,requested_by,requested_at,created_at,updated_at) VALUES(?,?,?,?,?,?,\'pending\',?,NOW(),NOW(),NOW())');$s->execute([TenantContext::id(),$clientId,$clientServiceId,$workflowId,$type,$roleId,Auth::id()]);return (int)Database::pdo()->lastInsertId();} public function decide(int $id,bool $approved,string $notes=''):void{$s=Database::pdo()->prepare('UPDATE approvals SET status=?,approved_by=?,decided_at=NOW(),decision_notes=?,updated_at=NOW() WHERE id=? AND tenant_id=?');$s->execute([$approved?'approved':'rejected',Auth::id(),$notes,$id,TenantContext::id()]);(new ActivityService)->log('approvals',$approved?'approved':'rejected','approval',$id,null,'stage_3');}}
